"""Mutants of task 2q-a: the architecture-metrics tool and its ratchet
(tools/gen2_metrics.py), the debt register's phase-close check
(tools/check_gen2_debt.py) and the locator-existence check
(tools/check_gen2_locators.py), each guard removed or weakened alone.

The headline mutants are the ones that LOOSEN the ratchet: a regression the
baseline should refuse passes (2Q-ratchet-*), an exemption that should not
hold holds (2Q-exempt-*), and a rebaseline records a regression or loosens a
threshold (2Q-rebaseline-*). The measurement mutants (2Q-graph-*, 2Q-cc-*,
2Q-cog-*, 2Q-hub-*, 2Q-unstable-*, 2Q-god-*, 2Q-collab-*) change what is
counted, so the numbers the ratchet compares are wrong. Every killer is a
black-box test of the tool on a throwaway repository: it fails by assertion.
"""
from __future__ import annotations

from .base import Mutation

MET, DEBT, LOC = "tools/gen2_metrics.py", "tools/check_gen2_debt.py", "tools/check_gen2_locators.py"
MG, MCY, MCO, MX, MSM, MH = ("test_metrics_measure.GraphTest.", "test_metrics_measure.CycleTest.", "test_metrics_measure.CollaborationTest.",
                             "test_metrics_measure.ComplexityTest.", "test_metrics_measure.SmellTest.", "test_metrics_measure.HistoryTest.")
RB, RP, RC, RCS, RK = ("test_metrics_ratchet.BaselineFileTest.", "test_metrics_ratchet.PropagationTest.", "test_metrics_ratchet.CycleTest.",
                       "test_metrics_ratchet.CycleShrinkTest.", "test_metrics_ratchet.CollaborationTest.")
RS, RF, RX, RR, RN, RE = ("test_metrics_ratchet.SmellTest.", "test_metrics_ratchet.FunctionTest.", "test_metrics_ratchet.CrossServiceTest.",
                          "test_metrics_ratchet.RebaselineTest.", "test_metrics_ratchet.ExemptedRegressionsAreNeverRecordedTest.",
                          "test_metrics_ratchet.ExemptionTest.")
DP, DE, DS, DT = "test_debt_register.PhaseCloseTest.", "test_debt_register.EntryTest.", "test_debt_register.StatusFileTest.", "test_debt_register.ToolFailureTest."
LF, LN, LS, LD = "test_locators.FileLocatorTest.", "test_locators.NotALocatorTest.", "test_locators.SymbolLocatorTest.", "test_locators.DottedLocatorTest."


def m(mid: str, description: str, killers: tuple[str, ...], old: str, new: str, target: str = MET) -> Mutation:
    return Mutation(f"2Q-{mid}", "2q", description, killers, target=target, old=old, new=new)


